function foundryScreen(s){return `<section class="station-screen foundry-screen"><div class="tora-nav"><button id="leaveStation" class="back-region">← Return to system</button><button id="rebuildStation" class="orbit-toggle">↻ Replay build</button></div><div class="tora-kicker">MEGASTRUCTURE SCHEMATIC <span>/</span> ${systemLink(s,s.name.toUpperCase())}</div><h2>${link('Foundry')}</h2><p class="tora-deck">Ancient Vy’Tiir stellar forge</p><nav class="tora-units" aria-label="Foundry source articles">${link('Dominion of Calidor','Codex source ↗')}${link('Foundry','Go to Article','tora-article')}</nav>${foundryElevation()}<div class="tora-instrument"><div class="tora-tags">${foundryParts.map((p,i)=>`<button data-part="${i}" aria-pressed="false"><small>0${i+1}</small> ${esc(p.title)}</button>`).join('')}</div><div id="partReadout" aria-live="polite"></div></div><div class="tora-specs">${[['Builders','Vy’Tiir'],['Location','Calidor stellar orbit'],['Role','Energy / stellar forge'],['Dimensions','Not documented']].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div><p class="foundry-lore">An ancient structure discovered by Calidor’s settlers, the Foundry sustains the capital system’s prosperity. The ${link('Dominion of Calidor','national record')} describes its output as near-limitless while also emphasizing finite capacity: diverting it to military production would cripple the civilian economy.</p><p class="tora-foot">Exterior geometry follows the supplied illustration. Component names are descriptive interpretations, not a documented internal plan. A dedicated ${link('Foundry','Foundry article')} was not available when this schematic was prepared.</p></section>`}
